#include <stdio.h>
#include <stdlib.h>

#define LIMBS 512
#define BASE 1000000000u

typedef struct { unsigned int d[LIMBS]; int n; } Big;

static void big_zero(Big *x) { x->n = 1; x->d[0] = 0u; }

static void big_add(Big *r, const Big *a, const Big *b) {
    int n = (a->n > b->n) ? a->n : b->n;
    unsigned long long carry = 0ull;
    int i = 0;
    for (; i < n; i++) {
        unsigned long long s = carry;
        if (i < a->n) s += a->d[i];
        if (i < b->n) s += b->d[i];
        r->d[i] = (unsigned int)(s % BASE);
        carry = s / BASE;
    }
    while (carry) {
        r->d[i] = (unsigned int)(carry % BASE);
        carry /= BASE;
        i++;
    }
    if (i == 0) i = 1;
    r->n = i;
}

static void big_print(const Big *x) {
    int i;
    printf("%u", x->d[x->n - 1]);
    for (i = x->n - 2; i >= 0; i--) printf("%09u", x->d[i]);
    printf("\n");
}

int main(int argc, char **argv) {
    long n, i;
    Big a, b, c;
    if (argc < 2) return 1;
    n = strtol(argv[1], NULL, 10);
