#include <stdio.h>
#include <stdlib.h>

#define BASE 1000000000u

static void big_add(const unsigned int *a, int na,
                    const unsigned int *b, int nb,
                    unsigned int *r, int *rn) {
    int n = (na > nb) ? na : nb;
    unsigned long long carry = 0ull;
    int i;
    for (i = 0; i < n; i++) {
        unsigned long long s = carry;
        if (i < na) s += a[i];
        if (i < nb) s += b[i];
        r[i] = (unsigned int)(s % BASE);
        carry = s / BASE;
    }
    if (carry) {
        r[i] = (unsigned int)carry;
        i++;
    }
    *rn = i;
}

static void big_print(const unsigned int *x, int n) {
    int i;
    printf("%u", x[n - 1]);
    for (i = n - 2; i >= 0; i--) printf("%09u", x[i]);
    printf("\n");
}

int main(int argc, char **argv) {
    long n, i;
    int la = 1, lb = 1, lc = 0, lt;
    unsigned int *a, *b, *c, *t;
    size_t cap;
    if (argc < 2) return 1;
    n = strtol(argv[1], NULL, 10);
    if (n < 0) n = 0;
    /* f(n) needs about n * 0.02322 base-1e9 limbs; n/32 + 16 is safely above */
    cap = (size_t)n / 32u + 16u;
    a = (unsigned int *)calloc(cap, sizeof(unsigned int));
    b = (unsigned int *)calloc(cap, sizeof(unsigned int));
    c = (unsigned int *)calloc(cap, sizeof(unsigned int));
    if (!a || !b || !c) return 1;
    b[0] = 1u;
    for (i = 0; i < n; i++) {
        big_add(a, la, b, lb, c, &lc);
        t = a; a = b; b = c; c = t;
        lt = la; la = lb; lb = lc; lc = lt;
    }
    big_print(a, la);
    free(a);
    free(b);
    free(c);
    return 0;
}
